// minerpg: Ascension and Fates (pack 1.8.0), the parts that hook mods for the whole run.
// Design: docs/superpowers/specs/2026-11-11-minerpg-ascension-design.md. The tab is generated by
// pack/tools/gen_ascension.py (which also writes kubejs/ascension/rules.json); the effects that data can't express
// are in server_scripts/minerpg_ascension_effects.js, the gate and migration in server_scripts/minerpg_ascension.js.
//
// A startup script: Spell Engine and Pufferfish keep their listeners for the whole run, and server scripts run again
// on every reload, so registering there would add a listener per reload. Changes here need a restart, not /reload.

const $AscSpellEvents = Java.loadClass('net.spell_engine.api.spell.event.SpellEvents')
const $AscCastAction = Java.loadClass('net.spell_engine.internals.casting.SpellCast$Action')

// Spell casts the effects script reacts to. Spell Engine tells us here, at release; the server script reads the
// player's persistent data (asc_cast_<spell path> = game time of the cast; asc_cast_target_<spell path> = the first
// target's entity id) on its next tick, so it can keep its logic reloadable.
const ASC_WATCHED_CASTS = {
  'minerpg:ascension_nightblade_ultimate': true,
  'minerpg:ascension_plaguefang_ultimate': true,
  'minerpg:ascension_juggernaut_ultimate': true,
  'minerpg:ascension_reaver_ultimate': true,
  'minerpg:ascension_lightbinder_ultimate': true,
  'minerpg:ascension_zealot_ultimate': true,
  'minerpg:ascension_bulwark_ultimate': true,
  'minerpg:ascension_crusader_ultimate': true,
  // Class spells that Transformations change.
  'rogues:charge': true,
  'rogues:last_stand': true,
  'rogues:shout': true,
  'rogues:mortal_strike': true,
  'paladins:divine_protection': true,
  'paladins:holy_beam': true,
  'paladins:judgement': true,
}

$AscSpellEvents.SPELL_CAST.register(args => {
  if (args.action() != $AscCastAction.RELEASE) return
  var key = args.spell().unwrapKey()
  if (!key.isPresent()) return
  var id = String(key.get().location())
  if (!ASC_WATCHED_CASTS[id]) return
  var caster = args.caster()
  if (caster.level.isClientSide()) return
  var path = id.substring(id.indexOf(':') + 1)
  var data = caster.getPersistentData()
  data.putLong('asc_cast_' + path, caster.level.getLevelData().getGameTime())
  var targets = args.targets()
  data.putInt('asc_cast_target_' + path, targets.isEmpty() ? -1 : targets.get(0).getId())
})

// Lightbinder heals. Spell Engine reports a heal after applying it; server_scripts/minerpg_ascension_effects.js stores
// a player's health just before every heal (asc_pre_heal), so overheal and "was below 30%" can be worked out here.
// The extra heals below use the plain heal, which doesn't report again, so nothing loops.
const $AscPlayerClass = Java.loadClass('net.minecraft.world.entity.player.Player')
const ASC_OVERFLOW_CAP = 12.0 // 6 hearts

function ascHealOwner(caster) {
  if (caster instanceof $AscPlayerClass) return caster
  // A summon (Lightwell) heals on its owner's behalf.
  var owner = caster.getOwner ? caster.getOwner() : null
  return owner instanceof $AscPlayerClass ? owner : null
}

$AscSpellEvents.HEAL.register(args => {
  var target = args.target()
  var caster = args.caster()
  if (target == null || caster == null || target.level.isClientSide()) return
  if (!(target instanceof $AscPlayerClass)) return
  var owner = ascHealOwner(caster)
  if (owner == null) return
  var tags = owner.getTags()
  var amount = args.amount()
  var data = target.getPersistentData()
  var before = data.contains('asc_pre_heal') ? data.getFloat('asc_pre_heal') : target.getHealth() - amount
  var max = target.getMaxHealth()

  if (tags.contains('asc_lightbinder_deep_1') && before < max * 0.3) target.heal(amount)
  if (tags.contains('asc_lightbinder_fate')) {
    var overflow = amount - Math.max(0, target.getHealth() - before)
    if (overflow > 0) target.setAbsorptionAmount(Math.min(ASC_OVERFLOW_CAP, target.getAbsorptionAmount() + overflow))
  }
  var key = args.spell().unwrapKey()
  if (tags.contains('asc_lightbinder_trans_2') && key.isPresent() && String(key.get().location()) == 'paladins:lightwell_heal') {
    var harmful = null
    target.getActiveEffects().forEach(inst => {
      if (harmful == null && !inst.getEffect().value().isBeneficial()) harmful = inst.getEffect()
    })
    if (harmful != null) target.removeEffect(harmful)
  }
  // Dawnfall: every heal also lands on every other ally within 12 blocks.
  var odata = owner.getPersistentData()
  if (odata.getLong('asc_until_dawn') > owner.level.getLevelData().getGameTime()) {
    var box = owner.getBoundingBox().inflate(12)
    owner.level.getEntitiesOfClass($AscPlayerClass, box).forEach(p => {
      if (p != target && p.distanceTo(owner) <= 12) p.heal(amount)
    })
  }
})
